root='.'
files=[]
for dp,ds,fs in os.walk(root):
 if any(x in dp.split(os.sep) for x in ['.git','node_modules']): continue
 for f in fs:
  if f.endswith('.go'): files.append(os.path.join(dp,f))
# strip comments/strings approximately, preserve lines
patdecl=re.compile(r'\bfunc\s+(?:\([^\n]*?\)\s+)?([A-Za-z_]\w*)\s*\(')
decls={}
for p in files:
 if not p.startswith('./internal/') and p!='./internal': continue
