 for p in files:
  s=open(p).read()
  for m in token.finditer(s):
   # skip declaration occurrence
   if any(p==dp and m.start()>=st and m.start()<st+100 for dp,st in ds): continue
   # don't count selector? include all
   cands=[c for c in contexts if c[0]==p and c[1]<=m.start()<c[2]]
   caller=cands[-1][3] if cands else '<top-level>'
   callers.add((p,caller)); occurrences+=1
 counts.append((len(callers),occurrences,name,ds))
for n,o,name,ds in sorted(counts,reverse=True)[:30]: print(n,o,name,ds[:4])
